"""Render a Claude Code session transcript (.jsonl) to readable Markdown, without editing content."""
import json, sys

src, dst, title = sys.argv[1], sys.argv[2], sys.argv[3]
out = [f"# {title}", "",
       f"Source: Claude Code session transcript `{src.split(chr(92))[-1]}` (raw JSONL included alongside).",
       "Rendered verbatim: user messages, assistant replies, tool calls and tool results in order. "
       "Internal harness records (request metadata, file snapshots) are omitted here but present in the raw JSONL.", ""]

def text_of(content):
    if isinstance(content, str):
        return content
    parts = []
    for c in content:
        if c.get("type") == "text":
            parts.append(c["text"])
        elif isinstance(c, dict) and "text" in c:
            parts.append(c["text"])
    return "\n".join(parts)

for line in open(src, encoding="utf-8"):
    d = json.loads(line)
    if d.get("type") not in ("user", "assistant"):
        continue
    msg = d.get("message") or {}
    ts = d.get("timestamp", "")
    content = msg.get("content")
    if d["type"] == "user":
        if isinstance(content, str):
            out += [f"## User  ({ts})", "", content, ""]
            continue
        for c in content or []:
            if c.get("type") == "text":
                out += [f"## User  ({ts})", "", c["text"], ""]
            elif c.get("type") == "tool_result":
                body = text_of(c.get("content", ""))
                out += [f"**Tool result** ({ts})", "", "````", body, "````", ""]
    else:
        for c in content or []:
            t = c.get("type")
            if t == "text" and c["text"].strip():
                out += [f"## Claude  ({ts})", "", c["text"], ""]
            elif t == "thinking" and c.get("thinking", "").strip():
                out += [f"*Claude reasoning ({ts}):*", "", "> " + c["thinking"].replace("\n", "\n> "), ""]
            elif t == "tool_use":
                out += [f"**Tool call: {c['name']}** ({ts})", "", "````json",
                        json.dumps(c.get("input"), indent=2, ensure_ascii=False), "````", ""]

open(dst, "w", encoding="utf-8").write("\n".join(out))
print("wrote", dst)

